SELECT *, COUNT(amount) OVER (PARTITION BY txn_type ORDER BY amount ASC, id ASC ROWS BETWEEN 3 PRECEDING AND CURRENT ROW) last4_count_amount, AVG(amount) OVER (PARTITION BY txn_type ORDER BY amount ASC, id ASC ROWS BETWEEN 3 PRECEDING AND CURRENT ROW) last4_avg_amount, MIN(amount) OVER (PARTITION BY txn_type ORDER BY amount ASC, id ASC ROWS BETWEEN 3 PRECEDING AND CURRENT ROW) last4_min_amount, SUM(amount) OVER (ORDER BY txn_time ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) running_amount FROM transactions WHERE HOUR(txn_time) BETWEEN 10 AND 18
